export const experimentOptions={"atoms": {"a": [["12", "Carbon-12"], ["14", "Carbon-14"]], "b": [["0", "Neutral"], ["1", "Singly positive"]], "labels": ["Isotope (Z=6)", "Charge state"], "unit": "neutrons / electrons", "choices": [["6/6", "6 neutrons / 6 electrons"], ["6/5", "6 neutrons / 5 electrons"], ["8/6", "8 neutrons / 6 electrons"], ["8/5", "8 neutrons / 5 electrons"]]}, "evidence": {"a": [["diffuse", "Spread-out positive charge"], ["nuclear", "Concentrated positive nucleus"]], "b": [["far", "Far from centre"], ["close", "Close approach"]], "labels": ["Model", "Alpha approach"], "unit": "qualitative deflection", "choices": [["small", "Small deflection"], ["large", "Strong deflection"]]}, "radiation": {"a": [["alpha", "Alpha"], ["beta", "Beta"]], "b": [["paper", "Paper"], ["aluminium", "Thin aluminium"]], "labels": ["Emission", "Barrier"], "unit": "qualitative transmission", "choices": [["stopped", "Stopped in the model"], ["passes", "Passes in the model"]]}, "equations": {"a": [["alpha", "Alpha example: parent A210 Z84"], ["beta", "Beta-minus example: parent A14 Z6"]], "b": [["mass", "Find daughter mass number A"], ["charge", "Find daughter atomic number Z"]], "labels": ["Supplied decay example", "Missing number"], "unit": "daughter number"}, "half-life": {"a": [["80", "80 original nuclei"], ["160", "160 original nuclei"]], "b": [["1", "One half-life"], ["2", "Two half-lives"]], "labels": ["Initial population", "Elapsed intervals"], "unit": "expected surviving nuclei"}, "hazards": {"a": [["sealed", "Sealed source"], ["dust", "Leaking dust contaminates surface"]], "b": [["near", "External source nearby"], ["away", "External source removed"]], "labels": ["Source condition", "External source position"], "unit": "radioactive material remaining on surface", "choices": [["no", "No deposited source material"], ["yes", "Contaminating source material remains"]]}, "background": {"a": [["8", "Background 8 counts/s"], ["12", "Background 12 counts/s"]], "b": [["40", "Total 40 counts/s"], ["60", "Total 60 counts/s"]], "labels": ["Measured background", "Measured total"], "unit": "source counts/s"}, "uses": {"a": [["tracer", "Signal must escape body"], ["local", "Deposit energy over a short distance"]], "b": [["alpha", "Alpha emission"], ["gamma", "Gamma emission"]], "labels": ["Physical purpose", "Emission"], "unit": "purpose match", "choices": [["match", "Matches this physical requirement"], ["mismatch", "Does not match this requirement"]]}, "fission": {"a": [["1", "One starting fission"], ["2", "Two starting fissions"]], "b": [["1", "One successful trigger each"], ["2", "Two successful triggers each"]], "labels": ["Initial generation", "Successful next-generation triggers"], "unit": "next-generation fissions"}, "fusion": {"a": [["1", "One supplied fusion event"], ["2", "Two supplied fusion events"]], "b": [["before", "Before: H-2 + H-3"], ["after", "After: He-4 + neutron"]], "labels": ["Number of copies", "Side of nuclear ledger"], "unit": "total nucleons"}};
export const tasksForRad1=(k,tier="Higher")=>rad1Tasks[k].filter(t=>!t.higher||tier==="Higher");
export const validRad1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericRad1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceRad1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;

export function experimentResult(k,a,b){const o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose the stated settings.');let value;
if(k==='atoms')value=(Number(a)-6)+'/'+(6-Number(b));
if(k==='evidence')value=a==='nuclear'&&b==='close'?'large':'small';
if(k==='radiation')value=a==='beta'&&b==='paper'?'passes':'stopped';
if(k==='equations')value=a==='alpha'?(b==='mass'?206:82):(b==='mass'?14:7);
if(k==='half-life')value=Number(a)/2**Number(b);
if(k==='hazards')value=a==='dust'?'yes':'no';
if(k==='background')value=Number(b)-Number(a);
if(k==='uses')value=(a==='tracer'&&b==='gamma')||(a==='local'&&b==='alpha')?'match':'mismatch';
if(k==='fission')value=Number(a)*Number(b);
if(k==='fusion')value=5*Number(a);
return{value,a,b};}
export const predictionValid=(k,v,r)=>experimentOptions[k].choices?v===r.value:numericRad1(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>x[0]===v)?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
